        '*GPUView*' { '系统工具' }
        '*Debuggable*' { '编程开发' }
        default { \$null }
    }

    if (\$cat) {
        if (-not \$newCats.ContainsKey(\$cat)) { \$newCats[\$cat] = @() }
        \$newCats[\$cat] += @{Name=\$name; Target=\$_.TargetPath; Args=\$_.Arguments}
    }
}

# 输出结果
\$newCats.Keys | Sort-Object | ForEach-Object {
