{"path": "_find_missing_shortcuts.ps1", "content": "$existing = @(Get-ChildItem -Recurse -Filter '*.lnk' -Path '快捷方式' | ForEach-Object { $_.BaseName.ToLower() })
$startMenu = 'C:\ProgramData\Microsoft\Windows\Start Menu\Programs'
$exclude = @('uninstall','changelog','help','website','release','documentation','about','manual','sample')
$newCats = @{}

Get-ChildItem $startMenu -Recurse -Filter '*.lnk' | ForEach-Object {
    $name = $_.BaseName
    $key = $name.ToLower()

    if ($key -in $existing) { return }

    $skip = $false
    foreach ($ex in $exclude) { if ($key -match [regex]::Escape($ex)) { $skip = $true; break } }
    if ($skip) { return }
    if ($key -match '^(卸载|uninstall|changelog|帮助|用户手册|检查更新|关于|配置|软件许可)') { return }
    if ($_.TargetPath -match 'uninst') { return }

    $cat = switch -Wildcard ($name) {
        '*Word*'       { '办公' }
        '*Excel*'      { '办公' }
        '*PowerPoint*' { '办公' }
        '*Publisher*'  { '办公' }
        '*Access*'     { '办公' }
        '*OneNote*'    { '办公' }
        '*微信*'        { '通讯社交' }
        '*钉钉*'        { '通讯社交' }
        '*QQ*'         { '通讯社交' }
        '*哔哩哔哩*'    { '媒体播放' }
        '*抖音*'        { '媒体播放' }
        '*优酷*'        { '媒体播放' }
        '*Steam*'      { '游戏娱乐' }
        '*Stellaris*'  { '游戏娱乐' }
        '*FreeOrion*'  { '游戏娱乐' }
        '*WeGame*'     { '游戏娱乐' }
        '*我的世界*'    { '游戏娱乐' }
        '*Python*'     { '编程开发' }
        '*Node.js*'    { '编程开发' }
        '*PowerShell*' { '编程开发' }
        '*Developer*'  { '编程开发' }
        '*Windows SDK*'  { '编程开发' }
        '*Performance*'  { '系统工具' }
        '*火绒*'         { '系统工具' }
        '*Task Manager*' { '系统工具' }
        '*Disk Cleanup*' { '系统工具' }
        '*Memory Diagnostic*' { '系统工具' }
        '*Recovery*'   { '系统工具' }
        '*Registry*'   { '系统工具' }
        '*Services*'   { '系统工具' }
        '*Steps Recorder*' { '系统工具' }
        '*Sticky Notes*' { '系统工具' }
        '*System Info*' { '系统工具' }
        '*System Config*' { '系统工具' }
        '*WinDjView*'   { '文献阅读' }
        '*E-book viewer*' { '文献阅读' }
        '*Edit E-book*'  { '文献阅读' }
        '*LRF viewer*'   { '文献阅读' }
        '*Blackmagic*' { '设计创作' }
        '*Fairlight*'  { '设计创作' }
        '*MuseHub*'    { '设计创作' }
        '*MySQL Installer*' { '数据库' }
        '*Watt*'       { '网络工具' }
        '*Radmin Viewer*' { '网络工具' }
        '*GPUView*'    { '系统工具' }
        '*Debuggable*' { '编程开发' }
        default { $null }
    }

    if ($cat) {
        if (-not $newCats.ContainsKey($cat)) { $newCats[$cat] = @() }
        $newCats[$cat] += $name
    }
}

Write-Host "`n缺失的应用（需要新建快捷方式）："
Write-Host "====================================`n"

$newCats.Keys | Sort-Object | ForEach-Object {
    Write-Host "=== $_ ==="
    $newCats[$_] | ForEach-Object { Write-Host "  $_" }
    Write-Host ""
}
"}

