$catMap = @{office='办公';games='游戏娱乐';dev='编程开发';design='设计创作';db='数据库';reader='文献阅读';net='网络工具';tools='系统工具'}
$created = 0

Get-ChildItem $startMenu -Recurse -Filter '*.lnk' | ForEach-Object {
    $name = $_.BaseName; $key = $name.ToLower()
    if ($key -in $existing) { return }
    foreach ($s in $skip) { if ($key -match [regex]::Escape($s)) { return } }
    if ($_.TargetPath -match 'uninst') { return }

    $cat = switch -Wildcard ($name) {
        '*Word*' { 'office' }; '*Excel*' { 'office' }; '*PowerPoint*' { 'office' }
        '*Publisher*' { 'office' }; '*OneNote*' { 'office' }; '*Access*' { 'office' }
        '*Steam*' { 'games' }; '*Stellaris*' { 'games' }; '*FreeOrion*' { 'games' }
        '*WeGame*' { 'games' }; '*Python*' { 'dev' }; '*Node*' { 'dev' }
        '*PowerShell*' { 'dev' }; '*Developer*' { 'dev' }; '*SDK*' { 'dev' }
        '*Debuggable*' { 'dev' }; '*Visual Studio*' { 'dev' }; '*Windows App Cert*' { 'dev' }
        '*Blend for Visual Studio*' { 'dev' }
        '*Blackmagic*' { 'design' }; '*Fairlight*' { 'design' }; '*MuseHub*' { 'design' }
        '*MySQL*' { 'db' }; '*WinDjView*' { 'reader' }; '*E-book*' { 'reader' }
        '*LRF*' { 'reader' }; '*Watt*' { 'net' }; '*Radmin Viewer*' { 'net' }
        '*System Configuration*' { 'tools' }; '*System Information*' { 'tools' }
        '*Task Manager*' { 'tools' }; '*Registry Editor*' { 'tools' }
        '*Services*' { 'tools' }; '*Disk Cleanup*' { 'tools' }
        '*Memory Diagnostics*' { 'tools' }; '*Recovery*' { 'tools' }
        '*Steps Recorder*' { 'tools' }; '*Sticky Notes*' { 'tools' }
        '*GPUView*' { 'tools' }; '*Windows Performance*' { 'tools' }
        '*Component Services*' { 'tools' }
    }

    if ($cat) {
        $folder = "快捷方式\" + $catMap[$cat]
        if (-not (Test-Path $folder)) { mkdir $folder -Force | Out-Null }

        $dest = Join-Path $folder ($_.Name)
