{"path": "_batch_create.ps1", "content": "# Batch create missing shortcuts - single-threaded, no encoding issues
$existing = @{}
Get-ChildItem -Recurse -Filter '*.lnk' -Path '快捷方式' | ForEach-Object {
    $existing[$_.BaseName.ToLower()] = $true
}

$wsh = New-Object -ComObject WScript.Shell
$sm = 'C:\ProgramData\Microsoft\Windows\Start Menu\Programs'

# Define what to add: [name contains, target folder]
$add = @(
    @('Word', '办公'), @('Excel', '办公'), @('PowerPoint', '办公'),
    @('Publisher', '办公'), @('OneNote', '办公'),
    @('Steam', '游戏娱乐'), @('Stellaris', '游戏娱乐'),
    @('FreeOrion', '游戏娱乐'), @('WeGame', '游戏娱乐'),
    @('Python 3.9', '编程开发'), @('Node.js', '编程开发'),
    @('PowerShell ISE', '编程开发'), @('Developer Command', '编程开发'),
    @('Visual Studio', '编程开发'), @('Windows App Cert', '编程开发'),
    @('Blend for Visual', '编程开发'),
    @('Blackmagic', '设计创作'), @('Fairlight', '设计创作'),
    @('MuseHub', '设计创作'),
    @('MySQL Installer', '数据库'),
    @('WinDjView', '文献阅读'), @('E-book viewer', '文献阅读'),
    @('Edit E-book', '文献阅读'), @('LRF viewer', '文献阅读'),
    @('Watt Toolkit', '网络工具'), @('Radmin Viewer', '网络工具'),
    @('GPUView', '系统工具'), @('Windows Performance', '系统工具'),
    @('Component Services', '系统工具'), @('Disk Cleanup', '系统工具'),
    @('Memory Diagnostics', '系统工具'), @('Recovery', '系统工具'),
    @('Registry Editor', '系统工具'), @('services', '系统工具'),
    @('System Configuration', '系统工具'), @('System Information', '系统工具'),
    @('Task Manager', '系统工具'), @('Steps Recorder', '系统工具'),
    @('Sticky Notes', '系统工具')
)

$created = 0
Get-ChildItem $sm -Recurse -Filter '*.lnk' | ForEach-Object {
    $name = $_.BaseName
    if ($existing.ContainsKey($name.ToLower())) { return }
    if ($name -match '^uninst|卸载') { return }
    if ($_.TargetPath -match 'uninst') { return }

    $targetFolder = $null
    foreach ($rule in $add) {
        if ($name -match [regex]::Escape($rule[0])) {
            $targetFolder = $rule[1]
            break
        }
    }

    if ($targetFolder) {
        $dest = Join-Path '快捷方式' $targetFolder
        if (-not (Test-Path $dest)) { New-Item -ItemType Directory -Path $dest -Force | Out-Null }
        $dstPath = Join-Path $dest $_.Name
        if (Test-Path $dstPath) { return }

        try {
            $dst = $wsh.CreateShortcut($dstPath)
            $dst.TargetPath = $_.TargetPath
            $dst.Arguments = $_.Arguments
            $dst.WorkingDirectory = $_.WorkingDirectory
            $dst.IconLocation = $_.IconLocation
            $dst.Save()
            Write-Host "+ $targetFolder/$($_.Name)"
            $created++
        } catch { Write-Host "x $($_.Name)" }
    }
}

Write-Host "`nDone! Created $created shortcuts"
"}

