$catDir = @{O='办公';G='游戏娱乐';D='编程开发';M='设计创作';B='数据库';R='文献阅读';N='网络工具';T='系统工具'}

$created = 0
Get-ChildItem $sm -Recurse -Filter '*.lnk' | ForEach-Object {
    $name = $_.BaseName
    if ($existing.ContainsKey($name.ToLower())) { return }
    if ($name -match '^uninst|卸载') { return }
    if ($_.TargetPath -match 'uninst') { return }

    $cat = $null
    foreach ($r in $rules) {
        if ($name -match [regex]::Escape($r[0])) { $cat = $r[1]; break }
    }
    if (-not $cat) { return }

    $folder = $catDir[$cat]
    $destDir = Join-Path $base $folder
    if (-not (Test-Path $destDir)) { New-Item -ItemType Directory -Path $destDir -Force | Out-Null }
    $dst = Join-Path $destDir $_.Name
    if (Test-Path $dst) { return }

    try {
        $s = $wsh.CreateShortcut($dst)
        $s.TargetPath = $_.TargetPath
        $s.Arguments = $_.Arguments
        $s.WorkingDirectory = $_.WorkingDirectory
        $s.IconLocation = $_.IconLocation
        $s.Save()
        Write-Host "+ $folder/$($_.Name)"
        $created++
    } catch { Write-Host "x $($_.Name)" }
}

Write-Host "`nDone! Created $created shortcuts"
"}

